function normalizeEmbed(value){
 if(!value)return null;let input=String(value).trim();if(input.startsWith('<')){const match=input.match(/<iframe\b[^>]*\bsrc\s*=\s*["']([^"']+)["']/i);if(!match)return null;input=match[1].replaceAll('&amp;','&');}
 try{const u=new URL(input);if(u.protocol!=='https:'||u.username||u.password||u.port)return null;const host=u.hostname.toLowerCase(),parts=u.pathname.split('/').filter(Boolean);let id;
 if(['youtube.com','www.youtube.com','m.youtube.com','youtu.be','www.youtube-nocookie.com','youtube-nocookie.com'].includes(host)){id=host==='youtu.be'?parts[0]:['embed','shorts','live'].includes(parts[0])?parts[1]:u.searchParams.get('v');if(!/^[\w-]{11}$/.test(id||''))return null;const out=new URL('https://www.youtube-nocookie.com/embed/'+id),start=u.searchParams.get('start')||u.searchParams.get('t');if(/^\d+$/.test(start||''))out.searchParams.set('start',start);return {url:out.href,provider:'YouTube',height:315};}
 if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(host)){id=host==='player.vimeo.com'&&parts[0]==='video'?parts[1]:parts[0];if(!/^\d+$/.test(id||''))return null;const out=new URL('https://player.vimeo.com/video/'+id);if(/^[a-f0-9]+$/i.test(u.searchParams.get('h')||''))out.searchParams.set('h',u.searchParams.get('h'));return {url:out.href,provider:'Vimeo',height:315};}
 if(host==='open.spotify.com'){if(parts[0]==='embed')parts.shift();if(!['track','album','playlist','artist','episode','show'].includes(parts[0])||!/^[a-zA-Z0-9]+$/.test(parts[1]||''))return null;return {url:'https://open.spotify.com/embed/'+parts.slice(0,2).join('/'),provider:'Spotify',height:352};}
 if(['soundcloud.com','www.soundcloud.com','w.soundcloud.com'].includes(host)){const track=host==='w.soundcloud.com'?new URL(u.searchParams.get('url')||''):u;if(track.protocol!=='https:'||!['soundcloud.com','www.soundcloud.com','api.soundcloud.com'].includes(track.hostname)||track.username||track.password)return null;return {url:'https://w.soundcloud.com/player/?url='+encodeURIComponent(track.href)+'&auto_play=false',provider:'SoundCloud',height:166};}
 return null;
 }catch{return null;}
}
function mediaSource(value){if(!value)return '';if(/^\/api\/av\/[a-f0-9-]{36}$/.test(value))return value;try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function detectAV(bytes,declared=''){
 const str=(a,b)=>String.fromCharCode(...bytes.slice(a,b));
 if(str(0,3)==='ID3'||bytes[0]===255&&(bytes[1]&224)===224)return 'audio/mpeg';
 if(str(0,4)==='RIFF'&&str(8,12)==='WAVE')return 'audio/wav';
 if(str(0,4)==='fLaC')return 'audio/flac';
 if(str(0,4)==='OggS')return declared==='video/ogg'?'video/ogg':'audio/ogg';
 if(bytes[0]===0x1a&&bytes[1]===0x45&&bytes[2]===0xdf&&bytes[3]===0xa3)return declared==='audio/webm'?'audio/webm':'video/webm';
 if(str(4,8)==='ftyp')return declared.startsWith('audio/')||/^M4[ABP] /.test(str(8,12))?'audio/mp4':'video/mp4';
 return '';
}
function parseByteRange(header,size){if(!header)return null;const m=/^bytes=(\d*)-(\d*)$/.exec(header);if(!m||!m[1]&&!m[2])return {invalid:true};let start,end;if(!m[1]){const count=Number(m[2]);if(!Number.isSafeInteger(count)||count<1)return {invalid:true};start=Math.max(0,size-count);end=size-1;}else{start=Number(m[1]);end=m[2]?Number(m[2]):size-1;}if(!Number.isSafeInteger(start)||!Number.isSafeInteger(end)||start<0||start>=size||end<start)return {invalid:true};return {start,end:Math.min(size-1,end)};}
